export function regionLandmark(index:number,color:string,seat:number):string {
 const tint=(k:number)=>{const n=parseInt(color.slice(1),16);return '#'+[n>>16&255,n>>8&255,n&255].map(v=>Math.round(k>=0?v+(255-v)*k:v*(1+k)).toString(16).padStart(2,'0')).join('')};
 return MODELS[index].replaceAll('var(--accent-dark)',tint(-.28)).replaceAll('var(--accent-light)',tint(.32)).replaceAll('var(--accent)',color).replace('>P1</text>',`>P${seat+1}</text>`);
}
